package com.company.skillplatform.workflow.infrastructure;
import com.company.skillplatform.adapter.application.AdapterRegistry;import com.company.skillplatform.adapter.domain.SkillAdapter;import com.company.skillplatform.artifact.infrastructure.entity.SkillArtifactEntity;import com.company.skillplatform.artifact.infrastructure.repository.SkillArtifactRepository;import com.company.skillplatform.compatibility.domain.*;import com.company.skillplatform.compatibility.infrastructure.repository.*;import com.company.skillplatform.storage.domain.ObjectStoragePort;import com.company.skillplatform.version.application.SkillFileService;import com.company.skillplatform.version.infrastructure.entity.SkillVersionEntity;import com.company.skillplatform.workflow.domain.PublicationPort;import java.io.ByteArrayInputStream;import java.util.*;import org.springframework.stereotype.Component;
@Component public class LifecycleOnlyPublicationAdapter implements PublicationPort{private final AdapterRegistry registry;private final SkillFileService files;private final ObjectStoragePort storage;private final PlatformRepository platforms;private final SkillArtifactRepository artifacts;private final SkillVersionCompatibilityRepository compatibilities;public LifecycleOnlyPublicationAdapter(AdapterRegistry r,SkillFileService f,ObjectStoragePort s,PlatformRepository p,SkillArtifactRepository a,SkillVersionCompatibilityRepository c){registry=r;files=f;storage=s;platforms=p;artifacts=a;compatibilities=c;}public void build(Long versionId){if(registry.descriptors().isEmpty())throw new IllegalStateException("No skill adapters registered");Map<String,byte[]> source=files.snapshot(versionId);SkillVersionEntity version=files.version(versionId);for(SkillAdapter adapter:registryAdapters()){var platform=platforms.findByPlatformKey(adapter.platformKey().toUpperCase()).orElseThrow();Set<OsType> targets=new LinkedHashSet<>();compatibilities.findByVersionId(versionId).stream().filter(c->c.getPlatform().getPlatformKey().equalsIgnoreCase(adapter.platformKey())).filter(c->c.getDeclaredStatus()!=CompatibilityStatus.UNSUPPORTED).map(c->c.getOsType()).forEach(targets::add);if(targets.isEmpty())targets.add(OsType.ANY);for(OsType os:targets){SkillAdapter.AdapterResult result=adapter.build(new SkillAdapter.AdapterRequest(version.getSkill().getSkillKey(),version.getCandidateVersion(),source,"overlays/"+adapter.platformKey().toLowerCase()+".yaml"));String base=version.getCandidateVersion()+"/"+adapter.platformKey().toLowerCase()+"/"+os.name().toLowerCase();String key="skills/"+version.getSkill().getSkillKey()+"/artifacts/"+base+".zip";String name="skill-"+version.getCandidateVersion()+"-"+adapter.platformKey().toLowerCase()+"-"+os.name().toLowerCase()+".zip";storage.put(key,new ByteArrayInputStream(result.artifact()),result.artifact().length,result.contentType());artifacts.save(new SkillArtifactEntity(version,platform,os.name(),"PLATFORM_SKILL",key,name,result.artifact().length,result.sha256(),adapter.adapterVersion(),null));}}}private List<SkillAdapter> registryAdapters(){return registry.descriptors().stream().map(d->registry.forPlatform(d.platformKey())).toList();}}
